const canvas=document.querySelector('canvas'),fallback=document.querySelector('[data-runtime-fallback]'),status=document.querySelector('[data-runtime-status]'),motion=document.querySelector('[data-motion-toggle]');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let gl,program,buffer,raf=0,frames=0,progress=reduced.matches?1:0,paused=false,disposed=false,inView=true,last=0,color=0,ctx,gain,osc,muted=false;
function shader(kind,source){const s=gl.createShader(kind);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}
function backup(){progress=1;canvas.hidden=true;fallback.removeAttribute('hidden');status.textContent='Statinis pakaitalas: 3D API nepasiekiama. Apdailos ir garso valdymas išlieka.';stop();}
function init(){try{gl=canvas.getContext('webgl',{preserveDrawingBuffer:true,antialias:true});if(!gl)return backup();program=gl.createProgram();const vs=shader(gl.VERTEX_SHADER,'attribute vec3 p;uniform float t;varying float shade;void main(){float a=-.5+t*.7;vec3 q=vec3(p.x*cos(a)+p.z*sin(a),p.y,-p.x*sin(a)+p.z*cos(a));shade=.5+q.z*.35;gl_Position=vec4(q.x*.65,q.y*.85,q.z*.3,1.6+q.z*.18);}'),fs=shader(gl.FRAGMENT_SHADER,'precision mediump float;uniform vec3 color;varying float shade;void main(){gl_FragColor=vec4(color*(shade+.35),1.);}');gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);gl.deleteShader(vs);gl.deleteShader(fs);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('link');buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);const points=[[-1,-.7,-.5],[1,-.7,-.5],[1,.7,-.5],[-1,.7,-.5],[-1,-.7,.5],[1,-.7,.5],[1,.7,.5],[-1,.7,.5]],faces=[[0,1,2,0,2,3],[4,7,6,4,6,5],[0,4,5,0,5,1],[3,2,6,3,6,7],[1,5,6,1,6,2],[0,3,7,0,7,4]];gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(faces.flat().flatMap(i=>points[i])),gl.STATIC_DRAW);gl.useProgram(program);const p=gl.getAttribLocation(program,'p');gl.enableVertexAttribArray(p);gl.vertexAttribPointer(p,3,gl.FLOAT,false,0,0);gl.enable(gl.DEPTH_TEST);status.textContent='Tikras WebGL 3D; garsas įjungiamas tik paspaudus.';draw();schedule();}catch{backup();}}
function draw(){if(!gl||disposed||gl.isContextLost())return;gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(.945,.918,.863,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform1f(gl.getUniformLocation(program,'t'),progress);gl.uniform3f(gl.getUniformLocation(program,'color'),...(color?[.18,.42,.38]:[.75,.36,.19]));gl.drawArrays(gl.TRIANGLES,0,36);frames++;}
function stop(){cancelAnimationFrame(raf);raf=0;last=0;}
function schedule(){if(!raf&&!paused&&!reduced.matches&&!disposed&&inView&&!document.hidden&&progress<1&&!canvas.hidden)raf=requestAnimationFrame(tick);}
function tick(time){raf=0;if(last)progress=Math.min(1,progress+(time-last)/1200);last=time;draw();schedule();}
motion.onclick=()=>{paused=!paused;motion.textContent=paused?'Tęsti judesį':'Pristabdyti judesį';motion.setAttribute('aria-pressed',String(paused));if(paused)stop();else schedule();};
document.querySelector('#color').onclick=()=>{color=1-color;document.querySelector('#choice').textContent='Apdaila: '+(color?'žalias patinos atspalvis':'varis');draw();};
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();backup();});canvas.addEventListener('webglcontextrestored',()=>{if(!disposed){canvas.hidden=false;fallback.setAttribute('hidden','');progress=1;init();}});
reduced.addEventListener('change',()=>{if(reduced.matches){progress=1;stop();draw();}else schedule();});
const observer=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;if(inView)schedule();else{stop();ctx?.suspend();}});observer.observe(canvas);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();ctx?.suspend();}else schedule();});
const audioStatus=document.querySelector('[data-audio-status]');document.querySelector('[data-audio-start]').onclick=async()=>{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){audioStatus.textContent='Garso pakaitalas: API nepasiekiama; objektas aprašytas tekstu.';return;}try{if(!ctx){ctx=new Audio();gain=ctx.createGain();gain.gain.value=.035;gain.connect(ctx.destination);osc=ctx.createOscillator();osc.type='sine';osc.frequency.value=220;osc.connect(gain);osc.start();}await ctx.resume();audioStatus.textContent='Garsas groja';}catch{audioStatus.textContent='Garso paleisti nepavyko';}};
document.querySelector('[data-audio-pause]').onclick=async()=>{if(ctx)await ctx.suspend();audioStatus.textContent='Garsas pristabdytas';};document.querySelector('[data-audio-mute]').onclick=()=>{muted=!muted;if(gain)gain.gain.value=muted?0:.035;document.querySelector('[data-audio-mute]').setAttribute('aria-pressed',String(muted));};
function dispose(){disposed=true;stop();observer.disconnect();if(gl){gl.deleteBuffer(buffer);gl.deleteProgram(program);}osc?.stop();ctx?.close();}
addEventListener('pagehide',dispose);window.atlasRuntime={get state(){return{progress,frames,active:Boolean(raf),disposed,mode:canvas.hidden?'fallback':'webgl'};},dispose};init();
